package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_clone_TriageGen2Test {

    @Test
    public void testCloneBasic() {
        Element original = Parser.parseBodyFragment("<div id='test' class='foo'>Hello</div>").body().child(0);
        Element cloned = original.clone();

        // Verify identity: should not be the same object
        Assert.assertNotSame("Clone should be a new instance", original, cloned);

        // Verify properties are copied
        Assert.assertEquals("Tag name should be identical", original.tagName(), cloned.tagName());
        Assert.assertEquals("ID should be identical", original.id(), cloned.id());
        Assert.assertEquals("Text content should be identical", original.text(), cloned.text());

        // Verify attributes
        Map<String, String> originalAttrs = original.attributes().asList().stream()
                .collect(java.util.stream.Collectors.toMap(a -> a.getKey(), a -> a.getValue()));
        Map<String, String> clonedAttrs = cloned.attributes().asList().stream()
                .collect(java.util.stream.Collectors.toMap(a -> a.getKey(), a -> a.getValue()));
        Assert.assertEquals("Attributes should be identical", originalAttrs, clonedAttrs);
    }

    @Test
    public void testCloneWithChildren() {
        Element original = Parser.parseBodyFragment("<div><span>Child</span></div>").body().child(0);
        Element cloned = original.clone();

        Assert.assertEquals("Child count should be identical", original.children().size(), cloned.children().size());
        Assert.assertEquals("Child tag name should be identical", original.child(0).tagName(), cloned.child(0).tagName());
        Assert.assertEquals("Child text should be identical", original.child(0).text(), cloned.child(0).text());

        // Verify deep copy structure (children shouldn't be the same objects)
        Assert.assertNotSame("Children should be new instances", original.child(0), cloned.child(0));
    }

    @Test
    public void testCloneWithComplexAttributes() {
        Element original = new Element(org.jsoup.parser.Tag.valueOf("div"), "");
        original.attr("data-custom", "value");
        original.attr("class", "class1 class2");
        original.attr("style", "color:red;");

        Element cloned = original.clone();

        Assert.assertEquals("data-custom", cloned.attr("data-custom"));
        Assert.assertEquals("class1 class2", cloned.attr("class"));
        Assert.assertEquals("color:red;", cloned.attr("style"));
    }

    @Test
    public void testCloneEmptyElement() {
        Element original = new Element(org.jsoup.parser.Tag.valueOf("br"), "");
        Element cloned = original.clone();

        Assert.assertEquals("Tag name should be identical", "br", cloned.tagName());
        Assert.assertTrue("Clone should be empty", cloned.children().isEmpty() && cloned.text().isEmpty());
    }

    @Test
    public void testCloneIndependence() {
        Element original = Parser.parseBodyFragment("<div><span>Original</span></div>").body().child(0);
        Element cloned = original.clone();

        // Modify clone
        cloned.tagName("p");
        cloned.attr("id", "new-id");
        cloned.child(0).text("Modified");

        // Verify original remains unchanged
        Assert.assertEquals("Original tag name should not change", "div", original.tagName());
        Assert.assertNull("Original ID should not change", original.id());
        Assert.assertEquals("Original child text should not change", "Original", original.child(0).text());
    }
}
